import hashlib,json,os,pathlib,socket,subprocess,sys,tempfile,time,unittest,urllib.request,shutil
ROOT=pathlib.Path.cwd()
WEB=ROOT/'client/apps/web'
def run(command,cwd=None,env=None,timeout=900):
 result=subprocess.run(command,cwd=cwd or ROOT,env=env or os.environ,text=True,capture_output=True,timeout=timeout)
 if result.returncode:raise AssertionError(str(command)+'\n'+result.stdout+'\n'+result.stderr)
 return result
class OwnedChain:
 def __init__(self,port):self.port=port;self.child=None
 def __enter__(self):
  with socket.socket() as probe:probe.bind(('127.0.0.1',self.port))
  self.child=subprocess.Popen(['/root/.foundry/bin/anvil','--host','127.0.0.1','--port',str(self.port),'--chain-id','125','--silent'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
  try:
   for _ in range(100):
    if self.child.poll() is not None:raise AssertionError('owned Anvil exited before dispatch')
    try:
     req=urllib.request.Request('http://127.0.0.1:'+str(self.port),data=b'{"jsonrpc":"2.0","id":1,"method":"eth_chainId","params":[]}',headers={'Content-Type':'application/json'})
     if json.load(urllib.request.urlopen(req,timeout=.5))['result']=='0x7d':break
    except OSError:time.sleep(.05)
   else:raise AssertionError('owned Anvil unavailable')
   time.sleep(.2)
   if self.child.poll() is not None:raise AssertionError('lost owned Anvil before dispatch')
   return self
  except BaseException:self.__exit__(None,None,None);raise
 def __exit__(self,*args):
  if self.child is not None:
   self.child.terminate()
   try:self.child.wait(timeout=5)
   except subprocess.TimeoutExpired:self.child.kill();self.child.wait()
def vitest(files,cwd=WEB,original=WEB/'vitest.config.ts',extra=(),env=None):
 with tempfile.TemporaryDirectory(prefix='kindle-native-vitest-') as directory:
  directory=pathlib.Path(directory);config=directory/'config.mts';report=directory/'report.json'
  # Existing aliases/environment preserved; all runtime cache state is private.
  imports='import original from '+json.dumps(str(original))+';\n' if original and pathlib.Path(original).is_file() else 'const original={};\n'
  config.write_text(imports+'import {mergeConfig} from '+json.dumps(str(WEB/'node_modules/vitest/dist/config.js'))+';\nexport default mergeConfig(original,{cacheDir:'+json.dumps(str(directory/'cache'))+',test:{cache:false,fileParallelism:false,maxWorkers:1,minWorkers:1}});')
  command=[str(WEB/'node_modules/.bin/vitest'),'run',*files,*extra,'--configLoader','runner','--config',str(config),'--reporter=json','--outputFile='+str(report)]
  result=run(command,cwd=cwd,env=env)
  if not report.is_file():raise AssertionError('actual native Vitest report missing')
  data=json.loads(report.read_text());count=data.get('numTotalTests')
  if data.get('success') is not True or type(count) is not int or count<=0 or data.get('numPassedTests')!=count:raise AssertionError('native test count missing or failed')
  if any(data.get(k,0)!=0 for k in ('numFailedTests','numPendingTests','numTodoTests')):raise AssertionError('native skipped/pending/todo/failure')
  suites=data.get('testResults',[]);assertions=[]
  if not suites:raise AssertionError('empty native suites')
  for suite in suites:
   if suite.get('status')!='passed':raise AssertionError('native suite did not pass')
   assertions.extend(suite.get('assertionResults',[]))
  if len(assertions)!=count or any(x.get('status')!='passed' or not x.get('fullName')for x in assertions):raise AssertionError('missing named native assertion proof')
  print(json.dumps({'native_vitest_passes':count,'native_test_names':[x['fullName']for x in assertions]}))
  return count
